const backtestDetails = $input.first().json.data;
const allTrades = $input.all().flatMap(item => item.json.data || []);

// Sort trades by PnL to find best and worst
const sortedByPnl = [...allTrades].sort((a, b) => (b.pnl || 0) - (a.pnl || 0));
const bestTrades = sortedByPnl.slice(0, 3);
const worstTrades = sortedByPnl.slice(-3).reverse();

// Get first 3 and last 3 trades chronologically
const sortedByTime = [...allTrades].sort((a, b) => 
  new Date(a.entryTime) - new Date(b.entryTime)
);
const firstTrades = sortedByTime.slice(0, 3);
const lastTrades = sortedByTime.slice(-3);

// Build Markdown report
const summary = backtestDetails.summary || {};
const report = `# Backtest Report

## Summary
- **Backtest ID**: ${backtestDetails.id}
- **Symbol**: ${backtestDetails.symbol}
- **Strategy**: ${backtestDetails.strategy}
- **Interval**: ${backtestDetails.interval}
- **Period**: ${backtestDetails.startTime} to ${backtestDetails.endTime}
- **Status**: ${backtestDetails.status}

## Performance Metrics
- **Total Trades**: ${summary.totalTrades || 0}
- **Win Rate**: ${(summary.winRate || 0).toFixed(2)}%
- **Net PnL**: $${(summary.netPnl || 0).toFixed(2)}
- **Return**: ${(summary.returnPercent || 0).toFixed(2)}%
- **Max Drawdown**: ${(summary.maxDrawdown || 0).toFixed(2)}%
- **Initial Balance**: $${(summary.initialBalance || 0).toFixed(2)}
- **Final Balance**: $${(summary.finalBalance || 0).toFixed(2)}

## First 3 Trades
${firstTrades.map((t, i) => `
### Trade ${i + 1}
- Entry: ${t.entryTime} @ $${t.entryPrice}
- Exit: ${t.exitTime} @ $${t.exitPrice || 'N/A'}
- Side: ${t.side}
- PnL: $${(t.pnl || 0).toFixed(2)}
`).join('')}

## Last 3 Trades
${lastTrades.map((t, i) => `
### Trade ${allTrades.length - 2 + i}
- Entry: ${t.entryTime} @ $${t.entryPrice}
- Exit: ${t.exitTime} @ $${t.exitPrice || 'N/A'}
- Side: ${t.side}
- PnL: $${(t.pnl || 0).toFixed(2)}
`).join('')}

## Top 3 Winners
${bestTrades.map((t, i) => `
### Winner ${i + 1}
- Entry: ${t.entryTime} @ $${t.entryPrice}
- Exit: ${t.exitTime} @ $${t.exitPrice || 'N/A'}
- Side: ${t.side}
- PnL: $${(t.pnl || 0).toFixed(2)}
`).join('')}

## Top 3 Losers
${worstTrades.map((t, i) => `
### Loser ${i + 1}
- Entry: ${t.entryTime} @ $${t.entryPrice}
- Exit: ${t.exitTime} @ $${t.exitPrice || 'N/A'}
- Side: ${t.side}
- PnL: $${(t.pnl || 0).toFixed(2)}
`).join('')}`;

return {
  json: {
    backtestId: backtestDetails.id,
    summary: summary,
    report: report,
    tradeCount: allTrades.length,
    backtestDetails: backtestDetails,
    trades: {
      first: firstTrades,
      last: lastTrades,
      best: bestTrades,
      worst: worstTrades
    }
  }
};
